// #Sireum

package frigate_threat_response_coordinator.Frigate_Threat_Response_Coordinator

import org.sireum._
import art._
import frigate_threat_response_coordinator._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait DefenseReadinessAssessor_Api {
  def id: Art.BridgeId
  def defenseEvidence_Id : Art.PortId
  def defenseCondition_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var defenseCondition: Frigate_Threat_Response_Coordinator.DefenseCondition.Type = $

  def put_defenseCondition(value : Frigate_Threat_Response_Coordinator.DefenseCondition.Type) : Unit = {
    Contract(
      Modifies(defenseCondition),
      Ensures(
        defenseCondition == value
      )
    )
    Spec {
      defenseCondition = value
    }

    Art.putValue(defenseCondition_Id, Frigate_Threat_Response_Coordinator.DefenseCondition_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class DefenseReadinessAssessor_Initialization_Api (
  val id: Art.BridgeId,
  val defenseEvidence_Id : Art.PortId,
  val defenseCondition_Id : Art.PortId) extends DefenseReadinessAssessor_Api

@datatype class DefenseReadinessAssessor_Operational_Api (
  val id: Art.BridgeId,
  val defenseEvidence_Id : Art.PortId,
  val defenseCondition_Id : Art.PortId) extends DefenseReadinessAssessor_Api {

  // Logika spec var representing port state for incoming data port
  @spec var defenseEvidence: Frigate_Threat_Response_Coordinator.DefenseEvidence = $

  def get_defenseEvidence() : Option[Frigate_Threat_Response_Coordinator.DefenseEvidence] = {
    Contract(
      Ensures(
        Res == Some(defenseEvidence)
      )
    )
    val value : Option[Frigate_Threat_Response_Coordinator.DefenseEvidence] = Art.getValue(defenseEvidence_Id) match {
      case Some(Frigate_Threat_Response_Coordinator.DefenseEvidence_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port defenseEvidence.  Expecting 'Frigate_Threat_Response_Coordinator.DefenseEvidence_Payload' but received ${v}")
        None[Frigate_Threat_Response_Coordinator.DefenseEvidence]()
      case _ => None[Frigate_Threat_Response_Coordinator.DefenseEvidence]()
    }
    return value
  }
}
